export const ACTIVE_CITIZEN_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu warga aktif",q:"'Warga yang aktif' paling tepat digambarkan sebagai orang yang...",options:["ikut menyumbang & memperbaiki keadaan di sekitarnya, bukan hanya menikmati & mengeluh","hanya memakai fasilitas umum tanpa peduli cara merawatnya","menunggu orang lain bertindak lebih dulu baru ikut membantu kalau terpaksa"],answer:0,explain:"Warga aktif merasa ikut bertanggung jawab atas lingkungan & masyarakatnya.",hint:"Menyumbang & memperbaiki, bukan cuma menikmati."},
{n:2,type:"mcq",micro:"Lingkaran masyarakat",q:"Kamu bisa berkontribusi pada berbagai tingkat, dari yang terdekat...",options:["hanya untuk diri sendiri saja","keluarga, kelas, RT/RW, sekolah, kota, negara, hingga dunia","hanya di tingkat negara saja, sedangkan lingkungan yang kecil tidak termasuk tempat berkontribusi"],answer:1,explain:"Kontribusi bisa dimulai dari lingkaran terdekat & meluas seiring kemampuan.",hint:"Dari keluarga sampai dunia."},
{n:3,type:"mcq",micro:"Gotong royong",q:"'Gotong royong' adalah...",options:["menyuruh orang lain bekerja sendirian sementara kita hanya melihat dan memberi perintah dari jauh","membayar orang lain agar mengerjakannya","mengerjakan sesuatu bersama-sama demi kepentingan bersama"],answer:2,explain:"Gotong royong adalah tradisi kerja sama yang menjadi kekuatan masyarakat Indonesia.",hint:"Kerja bersama untuk kepentingan bersama."},
{n:4,type:"mcq",micro:"Semua bisa berkontribusi",q:"Anak & remaja bisa berkontribusi pada masyarakat dengan cara...",options:["sesuai usia & kemampuan: membantu tetangga, ikut kerja bakti, menjaga adik, berbagi ilmu","tidak bisa apa-apa sampai dewasa karena belum punya kekuatan atau wewenang apa saja","hanya dengan uang yang disumbangkan ke lembaga sosial"],answer:0,explain:"Kontribusi tidak menunggu usia tertentu; selalu ada peran yang sesuai.",hint:"Sesuai usia & kemampuan."},
{n:5,type:"mcq",micro:"Tindakan kecil berarti",q:"Menyapa tetangga lansia & menanyakan kabarnya secara rutin...",options:["hanya membuang waktu saja karena tetangga lansia biasanya sudah terbiasa sendirian di rumahnya","adalah kontribusi nyata yang membangun rasa saling peduli di lingkungan","tidak ada gunanya karena perbuatan sekecil itu tidak berpengaruh pada lingkungan"],answer:1,explain:"Masyarakat yang hangat dibangun dari banyak tindakan kecil yang konsisten.",hint:"Kecil tapi membangun kepedulian."},
{n:6,type:"tf",micro:"Mengeluh vs berkontribusi",q:"Benar atau Salah: Mengeluh tentang masalah lingkungan berbeda dari ikut mengusahakan perbaikannya; keduanya tidak sama.",answer:true,explain:"Menyuarakan masalah bisa jadi awal yang baik, tetapi perubahan butuh tindakan, bukan keluhan saja.",hint:"Menyuarakan saja belum cukup."},
{n:7,type:"mcq",micro:"Warga yang terinformasi",q:"Sebelum ikut menyuarakan atau bertindak soal sebuah isu, warga yang baik...",options:["langsung ikut apa kata orang yang paling keras bersuara","tidak perlu tahu apa-apa tentang masalahnya karena yang penting ikut ramai bersama banyak orang","berusaha memahami masalahnya dari sumber tepercaya & mendengar berbagai pihak"],answer:2,explain:"Kontribusi yang berdasar pemahaman lebih tepat sasaran & tidak mudah disesatkan.",hint:"Pahami dulu dari sumber tepercaya."},
{n:8,type:"mcq",micro:"Menghormati sambil berkontribusi",q:"Saat ikut kegiatan warga, sikap yang menjaga kebersamaan:",options:["menghormati aturan & keputusan bersama meski berbeda pendapat, sambil tetap menyampaikan usul","memaksakan cara sendiri kepada semua peserta sampai yang lain terpaksa menuruti kemauanmu","ikut kegiatan hanya bila semuanya sesuai kemauanmu dan tidak ada yang berbeda pendapat"],answer:0,explain:"Kontribusi yang sehat berjalan bersama penghormatan pada proses & orang lain.",hint:"Hormati keputusan bersama + tetap usul."},
{n:9,type:"mcq",micro:"Relawan",q:"Menjadi relawan berarti...",options:["dipaksa ikut kegiatan tanpa boleh menolak","menyumbangkan waktu & tenaga untuk membantu tanpa mengharapkan bayaran","dibayar mahal untuk melakukan suatu pekerjaan tertentu dalam jangka waktu yang sudah ditetapkan"],answer:1,explain:"Kerelawanan adalah salah satu bentuk kontribusi warga yang paling langsung.",hint:"Menyumbang waktu & tenaga sukarela."},
{n:10,type:"mcq",micro:"Melapor masalah",q:"Menemukan lampu jalan mati atau jalan berlubang berbahaya, warga yang aktif...",options:["hanya menggerutu di rumah sambil membicarakan kerusakan itu tanpa melapor ke orang lain","menganggap itu bukan urusannya karena jalan umum adalah milik pemerintah & bukan milik warga biasa","melaporkannya ke pengurus RT/RW atau kanal pengaduan resmi agar ditindaklanjuti"],answer:2,explain:"Melaporkan masalah lewat jalur yang tepat adalah kontribusi yang sering diremehkan.",hint:"Laporkan lewat jalur resmi."},
{n:11,type:"tf",micro:"Kontribusi berkelanjutan",q:"Benar atau Salah: Satu kegiatan besar sekali lalu berhenti selalu lebih berdampak daripada kontribusi kecil yang rutin & berkelanjutan.",answer:false,explain:"Sebaliknya, perubahan nyata di masyarakat sering datang dari upaya kecil yang konsisten dalam waktu lama, bukan acara besar sesekali.",hint:"Rutin & konsisten lebih berdampak."},
{n:12,type:"mcq",micro:"Kontribusi lewat keahlian",q:"Kamu pandai menggambar. Cara berkontribusi lewat keahlian itu:",options:["membuat poster untuk kegiatan warga atau kampanye lingkungan sekolah","menyimpan kemampuan menggambar itu untuk diri sendiri saja supaya tidak ditiru oleh orang lain","menolak membantu kecuali ada yang membayar hasil gambarmu"],answer:0,explain:"Setiap keahlian bisa menjadi sumbangan; kontribusi tidak harus seragam.",hint:"Pakai keahlianmu untuk kepentingan bersama."},
{n:13,type:"tf",micro:"Bukan hanya urusan orang dewasa",q:"Benar atau Salah: Berkontribusi pada masyarakat sepenuhnya urusan orang dewasa, & pelajar harus menunggu dewasa dulu sebelum boleh memulai kegiatan.",answer:false,explain:"Sebaliknya, pelajar pun bisa memulai & memimpin kegiatan bermanfaat; banyak gerakan bermula dari inisiatif anak muda yang peduli.",hint:"Pelajar pun bisa memulai & memimpin."},
{n:14,type:"mcq",micro:"Menyumbang untuk sesama",q:"Saat ada warga terkena musibah, bentuk kontribusi yang bisa dilakukan pelajar:",options:["hanya menonton dari jauh sambil merekam kejadian untuk dibagikan","ikut mengumpulkan bantuan, menyumbang barang layak, atau membantu tenaga sesuai kemampuan","menganggap itu urusan pemerintah saja dan bukan urusan warga biasa seperti kita semua"],answer:1,explain:"Solidaritas pada sesama warga adalah inti dari masyarakat yang saling menjaga.",hint:"Ikut mengumpulkan & membantu."},
{n:15,type:"open",micro:"Kontribusimu sejauh ini",q:"Tuliskan satu hal yang pernah kamu lakukan untuk orang lain atau lingkungan di luar keluargamu, & bagaimana perasaanmu setelahnya.",explain:"Mengingat pengalaman berkontribusi memperkuat kebiasaan & rasa memiliki terhadap lingkungan.",hint:"Satu kontribusi nyata + perasaanmu.",sample:"Aku pernah ikut membersihkan selokan depan gang saat kerja bakti RT. Awalnya malas karena hari libur, tapi setelah selesai & melihat air mengalir lancar lagi, aku merasa bangga & jadi kenal beberapa tetangga yang sebelumnya cuma kulihat lewat. Sejak itu aku lebih semangat ikut kegiatan warga."},
{n:16,type:"mcq",micro:"Mendengar kebutuhan",q:"Sebelum membuat program bantuan untuk sebuah kelompok, langkah penting:",options:["langsung memberikan apa yang menurutmu bagus tanpa menanyakan apakah mereka benar-benar membutuhkannya","memberi bantuan lalu meminta pujian dari mereka serta dari banyak orang supaya dikenal dermawan","bertanya & mendengar apa yang benar-benar mereka butuhkan, bukan menebak sendiri"],answer:2,explain:"Kontribusi yang berguna dimulai dari mendengar, bukan mengasumsikan.",hint:"Tanya kebutuhan nyatanya dulu."},
{n:17,type:"tf",micro:"Kontribusi bukan soal pujian",q:"Benar atau Salah: Kontribusi yang tulus tetap berharga meski tidak ada yang memuji atau mengetahuinya.",answer:true,explain:"Motivasi mencari pujian rapuh; kontribusi yang bertahan lahir dari kepedulian yang tulus.",hint:"Tetap berharga tanpa pujian."},
{n:18,type:"mcq",micro:"Bekerja sama",q:"Kontribusi sering lebih besar dampaknya bila...",options:["dikerjakan bersama orang lain secara terorganisir daripada sendiri-sendiri","dilakukan diam-diam oleh satu orang saja","hanya dibicarakan berulang-ulang dalam banyak pertemuan tanpa pernah dijalankan dalam bentuk kegiatan"],answer:0,explain:"Banyak masalah masyarakat terlalu besar untuk satu orang; kerja sama melipatgandakan dampak.",hint:"Bersama & terorganisir lebih besar dampaknya."},
{n:19,type:"order",micro:"Dari peduli ke aksi",q:"Urutkan langkah mengubah kepedulian menjadi kontribusi nyata:",items:["Kenali satu masalah nyata di sekitarmu","Cari tahu penyebab & siapa yang terdampak","Rancang satu tindakan yang bisa kamu lakukan, sendiri atau bersama","Jalankan, lalu tinjau hasilnya & lanjutkan atau perbaiki"],answer:[0,1,2,3],explain:"Kenali masalah, pahami, rancang tindakan, lalu jalankan & evaluasi.",hint:"Kenali dulu, evaluasi terakhir."},
{n:20,type:"mcq",micro:"Ringkasan",q:"Inti menjadi warga yang peduli & berkontribusi adalah...",options:["menyerahkan seluruh tanggung jawab kepada pemerintah karena merekalah yang berwenang mengurus masyarakat","merasa ikut bertanggung jawab & mengambil bagian, sesuai kemampuan, untuk memperbaiki lingkungan & masyarakat","cukup menaati aturan yang ada & tidak lebih dari itu, karena selebihnya bukan urusan kita"],answer:1,explain:"Warga aktif melengkapi kepatuhan dengan partisipasi & kontribusi.",hint:"Ikut bertanggung jawab & mengambil bagian."},
{n:21,type:"classify",micro:"Aktif atau pasif",q:"Kelompokkan setiap sikap:",items:["Ikut kerja bakti membersihkan lingkungan","Mengeluh soal sampah tapi tidak pernah ikut membersihkan","Mengusulkan & membantu membuat taman baca warga","Menganggap semua masalah lingkungan bukan urusannya"],groups:["Warga aktif","Warga pasif"],answer:{"Warga aktif":["Ikut kerja bakti membersihkan lingkungan","Mengusulkan & membantu membuat taman baca warga"],"Warga pasif":["Mengeluh soal sampah tapi tidak pernah ikut membersihkan","Menganggap semua masalah lingkungan bukan urusannya"]},explain:"Warga aktif mengambil bagian dalam perbaikan; warga pasif hanya menonton atau mengeluh.",hint:"Mengambil bagian vs menonton/mengeluh."},
{n:22,type:"mcq",micro:"Keluhan yang membangun",q:"Agar keluhan berubah menjadi kontribusi, sebaiknya disertai...",options:["ancaman & kemarahan saja supaya pihak yang dikeluhkan segera merasa takut dan mau mengubah sikapnya","daftar nama orang yang harus disalahkan","usulan solusi & kesediaan ikut mewujudkannya"],answer:2,explain:"Kritik yang membangun menawarkan jalan keluar & ikut mengerjakannya.",hint:"Keluhan + usulan + kesediaan ikut."},
{n:23,type:"mcq",micro:"Satu kali vs berkelanjutan",q:"Kegiatan bersih pantai yang dilakukan sekali setahun untuk foto...",options:["kurang berdampak dibanding kebiasaan mengurangi sampah & merawat lingkungan sepanjang tahun","lebih baik daripada kebiasaan harian karena kegiatan besar yang ramai lebih mudah dikenang banyak orang","sudah cukup untuk menyelesaikan seluruh masalah sampah pantai tanpa perlu kebiasaan lain sepanjang tahun"],answer:0,explain:"Kontribusi simbolik sesekali kalah oleh kebiasaan kecil yang terus berjalan.",hint:"Kebiasaan sepanjang tahun > acara sekali."},
{n:24,type:"tf",micro:"Menumpang hidup bermasyarakat",q:"Benar atau Salah: Lingkungan yang bersih & aman akan tetap begitu selamanya meski tidak ada seorang pun warga yang ikut merawat & menjaganya.",answer:false,explain:"Sebaliknya, seperti milik bersama lainnya, kehidupan bermasyarakat menurun bila terlalu banyak yang hanya menumpang manfaat tanpa ikut merawat.",hint:"Semua menikmati, tak ada yang merawat = menurun."},
{n:25,type:"mcq",micro:"Jalur resmi",q:"Untuk masalah yang butuh kewenangan (perbaikan jalan, keamanan, perizinan kegiatan), warga aktif...",options:["hanya menyebarkan keluhan di media sosial","menempuh jalur resmi: lapor ke pengurus, ajukan usulan, ikuti prosedur","mengambil tindakan sendiri yang melanggar aturan karena jalur resminya dianggap terlalu lama dan berbelit"],answer:1,explain:"Beberapa perubahan hanya bisa lewat lembaga yang berwenang; menempuh jalurnya adalah bagian kontribusi.",hint:"Lewat jalur & prosedur resmi."},
{n:26,type:"mcq",micro:"Kontribusi & sekolah",q:"Bentuk kontribusi di lingkungan sekolah:",options:["hanya datang, duduk, & pulang setiap hari tanpa pernah ikut membantu apa-apa di sekolah","merusak fasilitas sekolah supaya pihak sekolah segera memperbaikinya dan memperhatikan kebutuhan murid","menjadi pengurus kelas atau OSIS, mengajari teman, merapikan fasilitas, memulai program bermanfaat"],answer:2,explain:"Sekolah adalah 'masyarakat kecil' tempat berlatih menjadi warga aktif.",hint:"Pengurus, mengajari, merawat, memulai program."},
{n:27,type:"mcq",micro:"Mentor sebaya",q:"Membantu adik kelas yang kesulitan pelajaran secara rutin adalah kontribusi karena...",options:["ilmu & waktu yang kamu bagikan meningkatkan orang lain tanpa mengurangi milikmu","hanya membuang waktu belajarmu sendiri sehingga nilai-nilaimu justru menjadi berkurang dalam ujian","hanya berguna bila ada yang membayar jasamu sebagai pengajar tambahan bagi adik-adik kelas"],answer:0,explain:"Berbagi pengetahuan adalah salah satu kontribusi yang paling berkelanjutan.",hint:"Berbagi ilmu menguatkan orang lain."},
{n:28,type:"tf",micro:"Kontribusi disesuaikan kemampuan",q:"Benar atau Salah: Kamu tidak harus melakukan hal besar untuk menjadi warga yang berkontribusi; memulai dari satu hal kecil yang konsisten sudah berarti.",answer:true,explain:"Menunggu bisa melakukan hal besar sering membuat orang tidak pernah mulai.",hint:"Mulai dari yang kecil & konsisten."},
{n:29,type:"mcq",micro:"Menemukan peran",q:"Cara menemukan bentuk kontribusi yang cocok untukmu:",options:["pilih yang paling terlihat mengesankan di mata banyak orang supaya kamu dipuji & dikenal luas","cocokkan minat & kekuatanmu (menulis, mengatur, mengajar, merawat tanaman) dengan kebutuhan di sekitarmu","tiru persis yang sedang dilakukan teman-temanmu tanpa memikirkan minat dan kemampuanmu"],answer:1,explain:"Kontribusi paling bertahan ketika sesuai dengan siapa kita & apa yang dibutuhkan.",hint:"Cocokkan kekuatanmu dengan kebutuhan."},
{n:30,type:"mcq",micro:"Menjaga semangat",q:"Agar tidak cepat lelah saat berkontribusi:",options:["mengerjakan semuanya sendirian sampai kewalahan agar hasilnya sempurna & tak ada yang mengganggu","berhenti begitu saja ketika sudah tidak ada lagi orang yang memuji atau mengucapkan terima kasih","bagi tugas, rayakan kemajuan kecil, & jaga keseimbangan dengan istirahat serta tanggung jawab lain"],answer:2,explain:"Kontribusi berkelanjutan menjaga diri sendiri agar bisa terus memberi.",hint:"Bagi tugas, rayakan kemajuan, jaga keseimbangan."},
{n:31,type:"mcq",micro:"Terapan: tetangga butuh bantuan",q:"Tetangga lansia kesulitan membawa belanjaan setiap minggu. Kontribusi sederhana:",options:["menawarkan bantuan membawakan secara rutin, dengan sopan & tanpa memaksa","menunggu sampai ia sendiri yang meminta bantuan","menganggap itu tugas keluarganya saja sehingga tetangga tidak perlu ikut membantu"],answer:0,explain:"Kepedulian pada tetangga adalah bentuk kewargaan yang paling dekat.",hint:"Tawarkan bantuan rutin dengan sopan."},
{n:32,type:"tf",micro:"Kontribusi menghormati martabat",q:"Benar atau Salah: Selama niat kita menolong, tidak masalah mempermalukan atau memfoto penerima bantuan sebagai tontonan.",answer:false,explain:"Sebaliknya, bantuan yang baik menjaga martabat penerima & membuatnya merasa dihormati, bukan direndahkan atau dijadikan tontonan.",hint:"Jaga martabat penerima bantuan."},
{n:33,type:"mcq",micro:"Terapan: kerja bakti",q:"Saat ada pengumuman kerja bakti RT di hari libur, sikap warga aktif:",options:["datang hanya untuk ikut makan bersama sesudah kegiatan selesai tanpa ikut bekerja sedikit pun","ikut hadir & membawa alat sebisanya, atau memberi kabar bila berhalangan & membantu di lain waktu","tidak datang tanpa kabar lalu menikmati hasil kerja bakti yang sudah dikerjakan warga"],answer:1,explain:"Ikut serta atau setidaknya memberi kabar & mengganti di waktu lain menjaga keadilan kontribusi.",hint:"Hadir & bawa alat, atau kabari & ganti."},
{n:34,type:"mcq",micro:"Terapan: memulai program kecil",q:"Kamu melihat banyak buku menganggur di rumah warga. Ide kontribusi:",options:["menyimpan idenya sendiri saja karena takut ditolak oleh pengurus & ditertawakan oleh warga lain","menunggu orang lain yang memulai terlebih dahulu baru kemudian ikut membantu kalau sudah ramai","mengusulkan & merintis pojok baca kecil di balai RT, mengumpulkan sumbangan buku, & mengatur jadwal"],answer:2,explain:"Warga aktif kadang perlu menjadi orang pertama yang bergerak.",hint:"Usulkan & rintis, jangan menunggu."},
{n:35,type:"mcq",micro:"Terapan: menyampaikan usulan ke RT",q:"Cara menyampaikan usulan kegiatan ke pengurus RT dengan baik:",options:["siapkan usulan tertulis singkat berisi tujuan, rencana, & bantuan yang kamu tawarkan, lalu sampaikan dengan sopan","datang tanpa persiapan lalu langsung menuntut pengurus RT agar menerima usulanmu","menyebarkan rencanamu kepada warga lain tanpa memberi tahu pengurus RT yang berwenang mengizinkannya"],answer:0,explain:"Usulan yang rapi & menawarkan bantuan lebih mungkin didukung.",hint:"Usulan tertulis + tawaran bantuan + sopan."},
{n:36,type:"order",micro:"Merancang proyek pelayanan",q:"Urutkan langkah merancang satu proyek pelayanan masyarakat kelas:",items:["Dengarkan & pastikan kebutuhan nyata kelompok yang akan dibantu","Tetapkan tujuan yang jelas & realistis","Bagi peran, kumpulkan sumber daya, & jalankan","Evaluasi dampaknya bersama pihak yang dibantu"],answer:[0,1,2,3],explain:"Pastikan kebutuhan, tetapkan tujuan, jalankan, lalu evaluasi bersama.",hint:"Dengar kebutuhan dulu, evaluasi bersama terakhir."},
{n:37,type:"mcq",micro:"Terapan: donasi",q:"Saat menggalang donasi untuk sebuah tujuan, praktik yang menjaga kepercayaan:",options:["memakai sebagian dana untuk keperluan pribadi panitia karena mereka sudah bekerja keras selama ini","jelaskan tujuannya, catat & laporkan pemasukan serta penggunaannya secara terbuka","mengumpulkan uang dari banyak orang tanpa pencatatan sehingga mudah dilupakan"],answer:1,explain:"Transparansi membuat orang mau menyumbang lagi & menjaga nama baik kegiatan.",hint:"Tujuan jelas + catatan & laporan terbuka."},
{n:38,type:"open",micro:"Masalah di sekitarmu",q:"Sebutkan satu masalah nyata di lingkungan atau sekolahmu yang kamu pedulikan, siapa yang terdampak, & satu langkah pertama yang bisa kamu lakukan.",explain:"Kontribusi dimulai dari memilih satu masalah nyata & satu langkah yang bisa dijalankan.",hint:"Masalah + yang terdampak + langkah pertama.",sample:"Masalah: jalan menuju sekolah gelap di beberapa titik sehingga rawan bagi murid yang pulang sore. Terdampak: murid & warga yang lewat, terutama perempuan & anak kecil. Langkah pertama: aku akan mencatat titik-titik gelapnya, memfotonya, & bersama beberapa teman menyampaikan ke wali kelas serta pengurus RT untuk diteruskan ke pihak yang berwenang."},
{n:39,type:"mcq",micro:"Terapan: bekerja sama dengan yang berbeda",q:"Dalam panitia kegiatan warga, ada anggota yang pendapatnya sering berbeda darimu. Sikap yang membangun:",options:["menyingkirkannya dari kepanitiaan supaya rapat tanpa perbedaan pendapat","mengabaikan semua idenya dalam setiap rapat meskipun sebagian di antaranya sebenarnya cukup baik","fokus pada tujuan bersama, dengarkan sudut pandangnya, & cari titik temu"],answer:2,explain:"Kontribusi yang efektif menuntut kemampuan bekerja dengan orang yang tidak selalu sepaham.",hint:"Fokus tujuan bersama + cari titik temu."},
{n:40,type:"tf",micro:"Bukan mencari panggung",q:"Benar atau Salah: Kontribusi yang baik berpusat pada kebutuhan orang yang dibantu & hasil nyata, bukan pada citra atau popularitas si penolong.",answer:true,explain:"Ketika fokus bergeser ke pencitraan, kontribusi mudah menjadi dangkal atau bahkan merugikan.",hint:"Pusatnya kebutuhan & hasil, bukan citra."},
{n:41,type:"mcq",micro:"Terapan: OSIS / pengurus kelas",q:"Menjadi pengurus kelas atau OSIS adalah kontribusi bila...",options:["kamu benar-benar menjalankan tugas mewakili & melayani teman, bukan sekadar mengejar jabatan","kamu hanya ingin namamu tercatat dalam daftar pengurus tanpa mau mengerjakan tugas","kamu memakai jabatan itu untuk mendapat keuntungan pribadi serta perlakuan istimewa dari teman-temanmu"],answer:0,explain:"Jabatan dalam organisasi siswa adalah amanah untuk melayani, bukan sekadar gengsi.",hint:"Menjalankan tugas melayani, bukan mengejar jabatan."},
{n:42,type:"mcq",micro:"Terapan: kanal pengaduan",q:"Kamu ingin melaporkan tumpukan sampah liar di lahan kosong. Langkah yang tepat:",options:["diamkan saja karena sudah biasa terjadi di lingkungan kita dan petugas akan tahu sendiri","laporkan ke pengurus RT/RW atau kanal pengaduan resmi kota, sertakan foto & lokasi jelas","buang sampahmu juga ke sana karena sudah terlanjur kotor"],answer:1,explain:"Laporan yang lengkap & lewat jalur resmi lebih cepat ditindaklanjuti.",hint:"Lapor ke jalur resmi + foto & lokasi."},
{n:43,type:"mcq",micro:"Terapan: mengajak teman",q:"Cara efektif mengajak teman ikut kegiatan sosial:",options:["memaksa & mempermalukan teman yang tidak mau ikut di depan orang banyak supaya merasa bersalah","melakukan semuanya sendirian sambil menyindir teman-teman yang lain karena tidak mau ikut kegiatan","jelaskan tujuan & manfaatnya, buat mudah diikuti, & ajak dengan antusias tanpa memaksa"],answer:2,explain:"Ajakan yang positif & mudah diikuti membuat lebih banyak orang bergabung.",hint:"Jelaskan manfaat + mudah diikuti + tanpa paksaan."},
{n:44,type:"tf",micro:"Kontribusi & tanggung jawab lain",q:"Benar atau Salah: Menjadi warga aktif berarti mengorbankan semua waktu belajar, istirahat, & keluarga demi kegiatan sosial.",answer:false,explain:"Sebaliknya, kontribusi yang berkelanjutan justru menjaga keseimbangan dengan belajar, kesehatan, & keluarga agar kita tidak kelelahan & bisa terus memberi.",hint:"Seimbangkan dengan belajar, sehat, keluarga."},
{n:45,type:"mcq",micro:"Terapan: proyek gagal sebagian",q:"Program bersih lingkungan yang kamu rintis hanya diikuti sedikit orang. Sikap yang matang:",options:["evaluasi apa yang bisa diperbaiki (waktu, ajakan, kemudahan), hargai yang sudah ikut, & coba lagi","menyerah dan menyimpulkan bahwa warga memang tidak peduli sehingga program tidak perlu dilanjutkan","menyalahkan warga yang tidak ikut serta dan menyebut mereka egois di depan banyak orang lain"],answer:0,explain:"Kontribusi jangka panjang menerima bahwa awal sering kecil & butuh perbaikan.",hint:"Evaluasi, hargai yang ikut, coba lagi."},
{n:46,type:"mcq",micro:"Terapan: membantu saat bencana",q:"Setelah bencana di daerahmu, cara pelajar berkontribusi dengan aman:",options:["hanya mengambil foto korban & lokasi bencana untuk diunggah di media sosial agar banyak yang melihat","ikut kegiatan yang dikoordinasi orang dewasa/lembaga, menyumbang barang yang dibutuhkan, & membantu sesuai arahan","masuk ke area berbahaya tanpa koordinasi dengan petugas supaya bisa langsung menolong lebih cepat"],answer:1,explain:"Bantuan yang terkoordinasi lebih aman & lebih tepat sasaran daripada tindakan sendiri-sendiri.",hint:"Ikut koordinasi + sumbang yang dibutuhkan."},
{n:47,type:"mcq",micro:"Terapan: menjaga fasilitas umum bersama",q:"Kamu & teman rutin merapikan taman kecil di depan sekolah. Ini termasuk kontribusi karena...",options:["tak ada yang menyuruh jadi kegiatan itu tidak dihitung sebagai kontribusi bagi sekolah","hanya berguna untuk kalian berdua saja","merawat ruang bersama membuatnya bermanfaat & nyaman untuk semua pengguna"],answer:2,explain:"Merawat milik bersama tanpa disuruh adalah bentuk kewargaan sehari-hari.",hint:"Merawat ruang bersama untuk semua."},
{n:48,type:"tf",micro:"Kontribusi lintas perbedaan",q:"Benar atau Salah: Kegiatan kontribusi masyarakat sebaiknya hanya boleh diikuti warga dari satu suku atau agama tertentu saja.",answer:false,explain:"Sebaliknya, kegiatan kontribusi sebaiknya terbuka bagi semua warga tanpa memandang latar belakang; kerja bersama justru mempererat keberagaman.",hint:"Terbuka untuk semua latar belakang."},
{n:49,type:"mcq",micro:"Terapan: usulan ditolak",q:"Usulan kegiatanmu ditolak pengurus karena keterbatasan dana. Langkah warga yang gigih:",options:["tanyakan syaratnya, perkecil skala usulan, cari sumber daya lain, & ajukan kembali","marah-marah lalu berhenti berpartisipasi untuk selama-lamanya","melakukannya diam-diam dengan melanggar keputusan pengurus karena merasa usulanmu bermanfaat"],answer:0,explain:"Kontribusi sering butuh kesabaran & penyesuaian, bukan menyerah pada penolakan pertama.",hint:"Sesuaikan skala, cari sumber daya, ajukan lagi."},
{n:50,type:"mcq",micro:"Terapan: menghargai relawan lain",q:"Dalam kegiatan bersama, cara menjaga semangat tim relawan:",options:["menganggap semua itu sudah seharusnya sehingga tak perlu terima kasih","mengakui & berterima kasih atas kontribusi setiap orang, sekecil apa pun","hanya memuji orang yang paling menonjol saja sedangkan yang bekerja diam-diam tidak perlu disebut"],answer:1,explain:"Penghargaan yang tulus membuat orang mau terus terlibat.",hint:"Akui & hargai kontribusi tiap orang."},
{n:51,type:"mcq",micro:"Terapan: menolak ajakan yang keliru",q:"Sekelompok warga mengajakmu 'main hakim sendiri' terhadap seseorang yang dicurigai. Sikap warga yang baik:",options:["ikut karena ramai-ramai supaya tidak dianggap pengecut oleh teman-temanmu","diam menonton dari kejauhan sambil menunggu hasilnya","menolak & mendorong agar masalah diserahkan ke pihak berwenang sesuai hukum"],answer:2,explain:"Kontribusi pada masyarakat termasuk menjaga agar tindakan warga tetap dalam koridor hukum & keadilan.",hint:"Tolak; serahkan ke pihak berwenang."},
{n:52,type:"order",micro:"Menggerakkan warga menghadapi satu masalah",q:"Urutkan langkah menggerakkan warga menghadapi masalah bersama (mis. lampu gang mati):",items:["Kumpulkan fakta: titik mana, sejak kapan, siapa terdampak","Bicarakan dengan tetangga & pengurus RT untuk menyepakati langkah","Ajukan ke pihak berwenang atau kumpulkan iuran bila memungkinkan","Pantau tindak lanjutnya & kabari warga"],answer:[0,1,2,3],explain:"Kumpulkan fakta, sepakati langkah, ajukan/atasi, lalu pantau & kabarkan.",hint:"Fakta dulu, pantau & kabari terakhir."},
{n:53,type:"mcq",micro:"Terapan: berbagi tanpa merendahkan",q:"Membagikan makanan untuk warga yang membutuhkan, cara yang menjaga martabat:",options:["membagikan dengan ramah & setara, tanpa memfoto wajah penerima untuk dipamerkan","meminta penerima berterima kasih di depan kamera","memberi hanya kepada orang yang mau mengemis & merendahkan dirinya terlebih dahulu di depan umum"],answer:0,explain:"Bantuan yang baik tidak menukar pertolongan dengan tontonan atau rasa malu penerimanya.",hint:"Ramah & setara, jangan jadikan tontonan."},
{n:54,type:"mcq",micro:"Terapan: mewakili suara teman",q:"Sebagai perwakilan kelas dalam forum sekolah, kontribusimu yang sejati:",options:["diam saja di forum karena takut salah bicara di depan banyak orang","menanyakan aspirasi teman lebih dulu, menyampaikannya, & melaporkan hasilnya kembali","menyampaikan pendapat pribadimu sebagai suara kelas supaya cepat selesai"],answer:1,explain:"Perwakilan yang berkontribusi membawa suara yang diwakilinya, bukan hanya dirinya.",hint:"Tanya aspirasi + sampaikan + laporkan kembali."},
{n:55,type:"mcq",micro:"Terapan: menjaga keberlanjutan program",q:"Program taman baca yang kamu rintis akan kamu tinggalkan karena naik jenjang sekolah. Langkah bertanggung jawab:",options:["menutup program itu begitu saja pada hari terakhirmu","membiarkannya berjalan tanpa ada seorang pun yang ditunjuk untuk bertanggung jawab melanjutkannya","siapkan & latih orang yang akan melanjutkan, & tinggalkan catatan cara mengelolanya"],answer:2,explain:"Kontribusi yang matang memikirkan kelanjutan setelah kita tidak lagi terlibat.",hint:"Siapkan penerus + tinggalkan panduan."},
{n:56,type:"open",micro:"Rencana kontribusi",q:"Rancang satu kontribusi nyata yang bisa kamu mulai bulan ini. Tulis: apa yang akan kamu lakukan, siapa yang terbantu, siapa yang kamu ajak, & bagaimana kamu tahu itu berhasil.",explain:"Kontribusi yang direncanakan dengan jelas, melibatkan orang lain, & punya ukuran keberhasilan lebih mungkin berjalan.",hint:"Apa + siapa terbantu + siapa diajak + ukuran berhasil.",sample:"Kontribusi: membuat jam belajar bersama gratis dua kali seminggu untuk adik-adik kelas 3-4 di balai RT. Yang terbantu: anak-anak yang orang tuanya sibuk & kesulitan mendampingi belajar. Yang kuajak: dua temanku yang juga suka mengajar, & minta izin serta dukungan pengurus RT. Ukuran berhasil: setidaknya lima anak datang rutin selama sebulan, & orang tua mereka merasa terbantu saat kutanya."},
{n:57,type:"mcq",micro:"Terapan: menanggapi kritik atas kegiatanmu",q:"Ada warga yang mengkritik cara kegiatan sosialmu dijalankan. Sikap yang matang:",options:["dengarkan, ambil masukan yang berguna untuk memperbaiki, & jelaskan dengan tenang bagian yang disalahpahami","tersinggung lalu menghentikan seluruh kegiatan karena merasa jerih payahmu tidak dihargai warga","mengabaikan semua kritik begitu saja karena menurutmu mereka tidak tahu apa-apa tentang kegiatanmu"],answer:0,explain:"Kritik bisa menjadi bahan perbaikan; warga aktif belajar dari umpan balik.",hint:"Dengar, ambil yang berguna, jelaskan dengan tenang."},
{n:58,type:"tf",micro:"Perubahan butuh banyak orang & waktu",q:"Benar atau Salah: Perubahan besar di masyarakat biasanya membutuhkan banyak orang yang bekerja bersama secara tekun dalam waktu yang lama, bukan satu tindakan hebat sekali jadi.",answer:true,explain:"Menyadari ini membuat kita tidak cepat kecewa & mau berkontribusi untuk jangka panjang.",hint:"Banyak orang + tekun + waktu lama."},
{n:59,type:"mcq",micro:"Terapan: memilih ikut atau memimpin",q:"Kamu tidak harus selalu menjadi pemimpin untuk berkontribusi. Peran anggota yang baik:",options:["ikut namanya saja dalam daftar anggota tanpa mengerjakan yang dibagikan kepadamu","menjalankan bagian yang diberikan dengan sungguh-sungguh & mendukung tim","hanya mau ikut bila ditunjuk menjadi ketua & menolak semua peran yang lain dalam kegiatan"],answer:1,explain:"Tim yang kuat butuh anggota yang bisa diandalkan, bukan hanya pemimpin.",hint:"Anggota yang andal juga berkontribusi besar."},
{n:60,type:"mcq",micro:"Terapan: kontribusi digital",q:"Cara berkontribusi lewat media sosial dengan bertanggung jawab:",options:["menyebarkan informasi tanpa diperiksa dulu kebenarannya asalkan sedang ramai dibicarakan banyak orang","menyerang orang-orang yang berbeda pendapat dengan kata-kata kasar di kolom komentar dan di grup","menyebarkan informasi bermanfaat & sudah diperiksa, mengajak aksi nyata, & menjaga sopan santun"],answer:2,explain:"Ruang digital bisa jadi alat kontribusi bila dipakai untuk hal yang benar & membangun.",hint:"Sebar info benar + ajak aksi nyata + sopan."},
{n:61,type:"mcq",micro:"Mengapa partisipasi menguatkan masyarakat",q:"Masyarakat dengan banyak warga aktif cenderung...",options:["lebih cepat menyelesaikan masalah bersama & punya rasa saling percaya yang lebih kuat","lebih lambat dalam menyelesaikan masalah & penuh konflik karena terlalu banyak orang yang ikut campur","tidak berbeda dari masyarakat pasif sebab jumlah warga aktif tidak berpengaruh"],answer:0,explain:"Partisipasi membangun jaringan, kepercayaan, & kemampuan kolektif menghadapi tantangan.",hint:"Masalah cepat selesai + saling percaya."},
{n:62,type:"mcq",micro:"Mendengar sebelum menolong",q:"Kesalahan umum dalam kegiatan sosial adalah...",options:["melibatkan masyarakat sejak awal dalam perencanaan kegiatan yang akan dilakukan untuk mereka sendiri","memberi apa yang menurut kita bagus tanpa menanyakan kebutuhan nyata masyarakat yang dibantu","bertanya terlalu banyak kepada masyarakat sampai kegiatan tak dimulai karena terus dibahas"],answer:1,explain:"Bantuan yang tidak sesuai kebutuhan bisa sia-sia atau bahkan menyulitkan penerimanya.",hint:"Jangan menebak kebutuhan; tanyakan."},
{n:63,type:"mcq",micro:"Kontribusi & hak orang lain",q:"Saat menjalankan kegiatan di ruang publik (menutup jalan untuk acara, memakai lapangan), warga aktif...",options:["menganggap niat baik cukup sehingga izin tidak perlu diurus","mengabaikan keberatan warga lain karena kegiatan itu dianggap lebih penting daripada kenyamanan mereka","meminta izin, memberi tahu warga terdampak, & meminimalkan gangguan"],answer:2,explain:"Kontribusi tidak boleh mengorbankan hak & kenyamanan warga lain tanpa persetujuan.",hint:"Izin + beri tahu + minimalkan gangguan."},
{n:64,type:"tf",micro:"Suara warga & kebijakan",q:"Benar atau Salah: Usulan atau keberatan warga tidak pernah berpengaruh pada pembuat kebijakan, meski disampaikan banyak orang lewat cara yang sah.",answer:false,explain:"Sebaliknya, ketika banyak warga menyampaikan usulan yang sama lewat cara yang sah, pembuat kebijakan lebih mungkin mempertimbangkannya; itulah kekuatan warga dalam demokrasi.",hint:"Suara banyak warga lewat cara sah = didengar."},
{n:65,type:"mcq",micro:"Menghindari rasa 'penyelamat'",q:"Sikap yang perlu dijaga saat membantu kelompok lain:",options:["memandang mereka sebagai mitra yang punya kekuatan & pengetahuan sendiri, bukan sekadar objek yang harus 'diselamatkan'","merasa lebih tinggi derajatnya karena kita yang memberi & menganggap mereka objek yang pasrah","mengharapkan mereka berterima kasih berlebihan, menuruti semua pendapat kita, & tidak boleh punya pandangan atau pengetahuan sendiri tentang apa yang paling mereka butuhkan"],answer:0,explain:"Kontribusi terbaik memberdayakan, bukan menciptakan ketergantungan atau merendahkan.",hint:"Mereka mitra, bukan objek diselamatkan."},
{n:66,type:"mcq",micro:"Mengukur dampak",q:"Cara sederhana menilai apakah kontribusimu berdampak:",options:["lihat berapa banyak pujian yang diterima dari orang-orang sesudah kegiatan itu selesai dilaksanakan","tanyakan pada pihak yang dibantu & lihat perubahan nyata, bukan hanya berapa banyak kegiatan diadakan","hitung berapa banyak foto kegiatan yang sudah diunggah ke media sosial dalam satu bulan terakhir"],answer:1,explain:"Dampak diukur dari perubahan yang dirasakan penerima, bukan dari keramaian kegiatan.",hint:"Tanya penerima + lihat perubahan nyata."},
{n:67,type:"mcq",micro:"Kontribusi jangka panjang: pendidikan",q:"Salah satu bentuk kontribusi jangka panjang yang bisa disiapkan pelajar:",options:["tidak perlu memikirkan masa depan karena kontribusi hanya bisa dilakukan ketika sudah dewasa","menghindari tanggung jawab selama mungkin supaya masa muda tetap menyenangkan tanpa beban","belajar sungguh-sungguh & mengembangkan keahlian yang kelak bisa dipakai memperbaiki masyarakat"],answer:2,explain:"Menjadi warga yang cakap & berintegritas di masa depan adalah kontribusi yang dimulai sekarang.",hint:"Belajar & kembangkan keahlian untuk masyarakat."},
{n:68,type:"tf",micro:"Menyalahkan tanpa berbuat",q:"Benar atau Salah: Terus-menerus menyalahkan pemerintah atau orang lain tanpa pernah ikut berbuat apa pun bukanlah bentuk kontribusi.",answer:true,explain:"Warga aktif boleh & perlu mengkritik, tetapi kritik yang membangun disertai kesediaan ikut memperbaiki.",hint:"Menyalahkan saja bukan kontribusi."},
{n:69,type:"mcq",micro:"Kontribusi & keberagaman peran",q:"Dalam sebuah gerakan atau kegiatan, peran yang dibutuhkan biasanya...",options:["beragam: ada yang mengatur, mencatat, menghubungi, membuat karya, mengajak, & mengerjakan lapangan","hanya satu jenis saja, yaitu pemimpin yang memberi perintah, sedangkan yang lain cukup menurut","tidak ada peran khusus karena semua pekerjaan akan berjalan sendiri bila niatnya baik"],answer:0,explain:"Karena perannya beragam, hampir setiap orang bisa menemukan tempat untuk berkontribusi.",hint:"Banyak jenis peran, ada tempat untuk semua."},
{n:70,type:"order",micro:"Dari ide menjadi gerakan kecil",q:"Urutkan langkah mengubah ide kontribusi menjadi gerakan kecil yang berjalan:",items:["Uji ide dengan beberapa orang & perbaiki berdasarkan masukan","Mulai kecil dengan satu kegiatan nyata","Ajak lebih banyak orang & bagi peran","Buat kegiatan itu rutin & siapkan penerus"],answer:[0,1,2,3],explain:"Uji ide, mulai kecil, perluas, lalu jadikan rutin & berkelanjutan.",hint:"Uji ide dulu, siapkan penerus terakhir."},
{n:71,type:"mcq",micro:"Kontribusi & integritas",q:"Kegiatan sosial yang dijalankan dengan integritas berarti...",options:["boleh sedikit berbuat curang asalkan tujuan akhir kegiatannya mulia dan bermanfaat bagi banyak orang","dana & sumber daya dipakai sesuai tujuan, laporan jujur, & janji kepada penerima ditepati","yang terpenting terlihat baik di mata orang luar, sedangkan isi di dalamnya tidak perlu terlalu diperiksa"],answer:1,explain:"Tujuan yang baik tidak membenarkan cara yang tidak jujur; kepercayaan adalah modal utama.",hint:"Sesuai tujuan + laporan jujur + tepati janji."},
{n:72,type:"mcq",micro:"Menilai sebuah ajakan kontribusi",q:"Sebelum ikut kegiatan atau menyumbang, pertanyaan yang baik:",options:["'Apakah banyak orang terkenal dan artis yang ikut serta di dalam kegiatan itu sehingga ramai?'","'Apakah ada hadiah atau keuntungan pribadi yang bisa langsung kuperoleh kalau aku ikut kegiatan ini?'","'Apa tujuannya, siapa penyelenggaranya, ke mana sumbangan digunakan, & apakah transparan?'"],answer:2,explain:"Kontribusi yang bijak memeriksa kejelasan tujuan & pengelolaan, bukan sekadar ikut ramai.",hint:"Tujuan, penyelenggara, penggunaan, transparansi."},
{n:73,type:"mcq",micro:"Kontribusi lintas lingkaran",q:"Menjaga kelas tetap rapi, ikut kerja bakti RT, & menghemat listrik di rumah menunjukkan bahwa...",options:["kewargaan yang baik terlihat dari kebiasaan sehari-hari di semua lingkaran kehidupan","hanya kegiatan besar yang tampak di media yang dihitung sebagai kontribusi bagi masyarakat luas","kontribusi hanya bisa dilakukan di satu tempat, misalnya di sekolah"],answer:0,explain:"Menjadi warga aktif adalah cara hidup, bukan sekadar ikut acara sesekali.",hint:"Kebiasaan sehari-hari di semua lingkaran."},
{n:74,type:"open",micro:"Refleksi peran & kekuatan",q:"Menurutmu, apa kekuatan atau minatmu yang paling bisa kamu sumbangkan untuk orang lain? Tulis satu cara memakainya dalam tiga bulan ke depan.",explain:"Menyadari kekuatan diri membantu menemukan kontribusi yang bisa dipertahankan.",hint:"Kekuatan/minatmu + satu cara memakainya.",sample:"Kekuatanku adalah sabar menjelaskan & suka anak kecil. Dalam tiga bulan ke depan aku ingin membuka bimbingan membaca gratis seminggu sekali untuk dua atau tiga anak tetangga yang belum lancar membaca, dengan izin & dukungan orang tua mereka. Aku akan mulai dari yang kecil supaya bisa kujaga terus."},
{n:75,type:"tf",micro:"Bukan semua atau tidak sama sekali",q:"Benar atau Salah: Kamu tidak harus menyelesaikan sebuah masalah besar sendirian untuk kontribusimu dianggap berarti; memperbaiki sebagian kecil pun berharga.",answer:true,explain:"Menuntut hasil sempurna sering membuat orang tidak pernah mulai; kemajuan sebagian tetap kemajuan.",hint:"Memperbaiki sebagian pun berarti."},
{n:76,type:"mcq",micro:"Kontribusi & belajar dari yang lebih berpengalaman",q:"Saat baru mulai aktif berkegiatan, sikap yang membantu:",options:["menolak masukan dari orang lain karena merasa caramu sendiri sudah paling benar","belajar dari warga atau kakak kelas yang sudah berpengalaman & mau bekerja sama","merasa sudah tahu segalanya sehingga tak perlu belajar dari orang berpengalaman"],answer:1,explain:"Menghargai pengalaman orang lain mempercepat pembelajaran & mencegah kesalahan yang sudah pernah terjadi.",hint:"Belajar dari yang berpengalaman."},
{n:77,type:"mcq",micro:"Kontribusi & rasa memiliki",q:"Orang cenderung lebih peduli & berkontribusi pada lingkungan bila...",options:["dibiarkan tidak tahu tentang rencana di lingkungannya","hanya diberi tahu setelah semua keputusan selesai dibuat oleh sekelompok kecil orang yang berwenang","merasa ikut memiliki & dilibatkan dalam keputusan tentang lingkungan itu"],answer:2,explain:"Rasa memiliki tumbuh dari keterlibatan; itu mendorong kontribusi yang tulus.",hint:"Dilibatkan -> merasa memiliki -> berkontribusi."},
{n:78,type:"mcq",micro:"Menjaga diri saat berkontribusi",q:"Bila kegiatan sosial mulai membuatmu sangat lelah atau mengganggu kewajiban pentingmu, langkah bijak:",options:["bicarakan dengan tim, kurangi beban atau atur ulang peranmu, & jaga keseimbangan","memaksakan diri terus bekerja sampai jatuh sakit karena merasa kegiatan itu tidak boleh ditinggalkan","berhenti mendadak tanpa memberi tahu sehingga rekanmu kebingungan"],answer:0,explain:"Kontribusi yang berkelanjutan menjaga si pemberi agar tetap sehat & bisa terus terlibat.",hint:"Bicara ke tim, atur ulang, jaga keseimbangan."},
{n:79,type:"mcq",micro:"Menyemangati warga lain",q:"Cara membuat lebih banyak orang mau ikut berkontribusi:",options:["menyimpan semua keberhasilan untuk diri sendiri supaya tidak ada yang menirunya","tunjukkan hasil nyata, ceritakan dampaknya, & buat langkah pertama untuk ikut jadi mudah","mempermalukan orang-orang yang belum ikut supaya mereka merasa bersalah dan akhirnya mau bergabung"],answer:1,explain:"Orang lebih tergerak oleh contoh & hasil nyata daripada oleh ceramah atau rasa bersalah.",hint:"Tunjukkan hasil + permudah langkah pertama."},
{n:80,type:"mcq",micro:"Gambaran warga yang berkontribusi",q:"Gambaran warga yang peduli & berkontribusi:",options:["hanya menaati aturan yang berlaku & tidak mengerjakan hal lain untuk kebaikan lingkungannya, walau ia punya kesempatan","mengkritik keadaan di sekitarnya tetapi tidak ikut berbuat untuk memperbaikinya","terinformasi, mengambil bagian sesuai kemampuan, bekerja sama, menjaga integritas, & melakukannya secara berkelanjutan"],answer:2,explain:"Kewargaan aktif menggabungkan pemahaman, partisipasi, kerja sama, kejujuran, & ketekunan.",hint:"Terinformasi, ambil bagian, kerja sama, jujur, berkelanjutan."},
{n:81,type:"mcq",micro:"Skenario: melihat masalah & mengorganisir",q:"Selokan di kompleksmu tersumbat & sering menyebabkan genangan. Langkah warga aktif:",options:["kumpulkan tetangga yang peduli, sepakati rencana bersih & jadwal rutin, & ajukan perbaikan permanen ke pengurus","menunggu sampai banjir benar-benar datang baru kemudian beramai-ramai mencari cara untuk mengatasinya","hanya membersihkan bagian selokan di depan rumahmu sendiri sedangkan bagian lainnya dibiarkan saja"],answer:0,explain:"Masalah bersama diselesaikan dengan menggerakkan warga & menempuh jalur perbaikan yang lebih besar.",hint:"Kumpulkan warga + rencana + ajukan perbaikan."},
{n:82,type:"tf",micro:"Inisiatif satu orang bisa memulai gerakan",q:"Benar atau Salah: Sebuah gerakan warga tidak mungkin dimulai kecuali sudah ada banyak orang yang siap sejak awal.",answer:false,explain:"Sebaliknya, banyak kegiatan warga yang besar justru bermula dari satu atau dua orang yang memutuskan mulai bergerak & mengajak orang lain.",hint:"Gerakan besar sering mulai dari satu-dua orang."},
{n:83,type:"mcq",micro:"Skenario: teman merasa sia-sia",q:"Temanmu berkata 'ngapain repot ikut kegiatan warga, nggak akan mengubah apa-apa'. Respons yang membangun:",options:["memaksanya ikut kegiatan dengan marah-marah & menyebutnya egois di depan teman lain","tunjukkan contoh perubahan kecil yang pernah berhasil, & ajak ikut satu kegiatan yang ringan untuk merasakannya sendiri","setuju dengan temanmu & ikut tidak peduli, karena kalau satu orang saja tidak bisa mengubah apa-apa maka kegiatan warga memang tidak ada gunanya untuk diikuti"],answer:1,explain:"Rasa berdaya sering tumbuh setelah seseorang mengalami sendiri bahwa tindakannya berpengaruh.",hint:"Tunjukkan contoh + ajak coba satu kegiatan."},
{n:84,type:"mcq",micro:"Skenario: proyek pelayanan sekolah",q:"Kelasmu ingin membuat proyek membantu panti atau kampung sekitar. Langkah pertama yang benar:",options:["langsung mengumpulkan barang yang menurut kalian dibutuhkan mereka tanpa bertanya lebih dulu","mengumumkan proyek itu di media sosial terlebih dahulu supaya banyak orang tahu & ikut menyumbang","hubungi & kunjungi pihak yang akan dibantu untuk mendengar kebutuhan mereka sebelum menyusun rencana"],answer:2,explain:"Proyek pelayanan yang baik dimulai dari mendengar, bukan dari asumsi atau publikasi.",hint:"Dengar kebutuhan mereka lebih dulu."},
{n:85,type:"mcq",micro:"Skenario: mencalonkan diri jadi pengurus",q:"Kamu mempertimbangkan mencalonkan diri jadi ketua OSIS. Alasan yang tepat:",options:["kamu punya gagasan konkret untuk memperbaiki sesuatu & siap bekerja melayani teman-teman","kamu ingin jabatan itu agar terlihat hebat di mata teman","teman-temanmu memaksamu mencalonkan diri walaupun kamu sendiri tidak peduli pada tugas yang akan dijalankan"],answer:0,explain:"Jabatan dalam organisasi siswa adalah sarana kontribusi, dinilai dari niat melayani & rencana kerja.",hint:"Gagasan konkret + siap melayani."},
{n:86,type:"mcq",micro:"Skenario: menyeimbangkan sekolah & kegiatan",q:"Kegiatanmu sebagai relawan mulai membuat nilaimu turun. Langkah bijak:",options:["berhenti dari kegiatan tanpa memberi tahu orang lain lalu menyalahkan kegiatan itu atas turunnya nilaimu","atur ulang jadwal, kurangi peran sementara, & minta bantuan tim agar kegiatan tetap jalan","berhenti sekolah saja demi kegiatan relawan karena menurutmu itu lebih penting daripada belajar"],answer:1,explain:"Kontribusi jangka panjang membutuhkan keseimbangan; belajar tetap tanggung jawab utama pelajar.",hint:"Atur ulang + kurangi sementara + minta bantuan tim."},
{n:87,type:"mcq",micro:"Skenario: sumbangan disalahgunakan",q:"Kamu tahu sebagian dana kegiatan sosial dipakai tidak sesuai tujuan oleh panitia. Sikap warga yang berintegritas:",options:["diam saja karena merasa tidak enak hati kepada panitia yang sudah lama bekerja keras bersama","ikut memakai sebagian dana itu juga untuk keperluan pribadimu supaya kamu tidak merasa dirugikan","sampaikan keberatan ke penanggung jawab & minta transparansi; bila perlu, laporkan lewat jalur yang tepat"],answer:2,explain:"Menjaga kejujuran pengelolaan sumber daya bersama adalah bagian dari kontribusi yang bertanggung jawab.",hint:"Minta transparansi; laporkan bila perlu."},
{n:88,type:"order",micro:"Menjaga gerakan tetap hidup",q:"Urutkan langkah agar sebuah kegiatan warga tidak berhenti setelah semangat awal mereda:",items:["Jadikan kegiatan itu rutin dengan jadwal & pembagian tugas yang jelas","Rayakan & bagikan hasil kecil untuk menjaga semangat","Rekrut & latih anggota baru secara berkala","Wariskan kepemimpinan & catatan pengelolaan sebelum yang lama berhenti"],answer:[0,1,2,3],explain:"Rutinkan, jaga semangat lewat hasil, rekrut penerus, lalu wariskan kepemimpinan.",hint:"Rutinkan dulu, wariskan kepemimpinan terakhir."},
{n:89,type:"mcq",micro:"Skenario: warga menolak kegiatanmu",q:"Sebagian warga keberatan pada kegiatan bersih lingkungan yang kamu adakan karena dianggap mengganggu. Sikap yang matang:",options:["dengarkan keberatannya, sesuaikan waktu atau cara agar tidak mengganggu, & jelaskan manfaatnya","tetap menjalankan kegiatan tanpa memedulikan keberatan warga","membatalkan kegiatan itu begitu saja lalu memendam rasa kesal terhadap warga yang menyampaikan keberatan"],answer:0,explain:"Kontribusi yang baik menghormati warga lain & mencari cara yang bisa diterima bersama.",hint:"Dengar keberatan + sesuaikan + jelaskan manfaat."},
{n:90,type:"mcq",micro:"Skenario: peluang menyuarakan ke pemerintah",q:"Ada forum musyawarah perencanaan pembangunan yang membuka masukan warga, termasuk lewat perwakilan. Sikap warga aktif:",options:["menuntut hal-hal yang mustahil dilakukan dan tidak masuk akal sehingga usulanmu tidak ditanggapi","ikut menyiapkan usulan yang konkret & beralasan (mis. taman, trotoar, penerangan) & menyampaikannya lewat jalur itu","mengabaikan forum itu lalu mengeluh keras-keras setelah pembangunan selesai dikerjakan oleh pemerintah"],answer:1,explain:"Memanfaatkan saluran resmi untuk menyampaikan usulan adalah salah satu kontribusi warga yang paling berdampak.",hint:"Siapkan usulan konkret & sampaikan lewat forumnya."},
{n:91,type:"mcq",micro:"Skenario: kontribusi setelah lulus",q:"Kamu akan pindah sekolah & meninggalkan komunitas belajar yang kamu rintis. Cara paling bertanggung jawab:",options:["menutup komunitas itu pada hari terakhirmu bersekolah supaya tidak ada yang menggantikan","membiarkan komunitas berjalan tanpa arahan dari orang lain setelah kamu pergi dari sekolah, lalu berharap semuanya baik-baik saja","latih dua adik kelas untuk melanjutkan, buat panduan sederhana, & tetap sesekali memberi dukungan dari jauh"],answer:2,explain:"Kontribusi yang matang memastikan manfaatnya berlanjut setelah kita pergi.",hint:"Latih penerus + panduan + dukungan dari jauh."},
{n:92,type:"open",micro:"Ikrar warga",q:"Tulis ikrar singkat untuk dirimu sendiri tentang bagaimana kamu ingin menjadi warga di lingkungan, sekolah, & negaramu.",explain:"Menuliskan ikrar mengikat niat & menjadi pengingat arah sebagai warga yang aktif.",hint:"Sebutkan sikap konkret di beberapa lingkaran kehidupan.",sample:"Aku ingin menjadi warga yang tidak hanya menuntut haknya, tetapi juga menjalankan kewajibannya & ikut memperbaiki keadaan. Aku akan menaati aturan yang adil & menyuarakan yang tidak adil lewat cara yang benar; menghormati semua orang apa pun latar belakangnya; menjaga milik bersama & lingkungan; ikut musyawarah & menghormati keputusan bersama; serta menyumbang waktu, tenaga, atau keahlianku untuk orang lain, sekecil apa pun, secara konsisten."},
{n:93,type:"mcq",micro:"Skenario: gerakan besar butuh kesabaran",q:"Kamu ikut mengupayakan penambahan jalur sepeda di kotamu, tetapi setelah setahun belum ada hasil. Sikap yang tepat:",options:["lanjutkan dengan sabar: kumpulkan lebih banyak dukungan & data, jaga komunikasi dengan pihak berwenang, & rayakan kemajuan kecil","menyerah saja karena sudah terlalu lama menunggu & hasilnya belum juga terlihat sedikit pun","menyimpulkan bahwa partisipasi warga tidak berguna sehingga tidak perlu dicoba lagi di kemudian hari, lalu mengajak orang lain berhenti juga"],answer:0,explain:"Perubahan kebijakan biasanya lambat; ketekunan & kerja sama yang berkelanjutan adalah kuncinya.",hint:"Sabar, tambah dukungan & data, jaga komunikasi."},
{n:94,type:"tf",micro:"Kewargaan aktif adalah kebiasaan seumur hidup",q:"Benar atau Salah: Kebiasaan peduli & berkontribusi yang dibangun sejak pelajar cenderung berlanjut menjadi warga dewasa yang terlibat dalam masyarakat & negaranya.",answer:true,explain:"Sekolah & lingkungan adalah tempat berlatih; kebiasaan hari ini membentuk warga negara di masa depan.",hint:"Kebiasaan pelajar membentuk warga dewasa."},
{n:95,type:"mcq",micro:"Skenario: banyak yang bisa dikerjakan, waktu terbatas",q:"Kamu peduli pada banyak masalah tapi waktumu terbatas. Cara memilih:",options:["tidak memilih apa-apa karena bingung & merasa semua masalah sama pentingnya untuk segera diurus","pilih satu atau dua yang paling kamu pedulikan & paling bisa kamu pengaruhi, lalu kerjakan dengan sungguh-sungguh","mencoba menangani semua masalah sekaligus dalam waktu singkat lalu akhirnya kelelahan dan berhenti total"],answer:1,explain:"Kontribusi yang terfokus & konsisten lebih berdampak daripada tersebar tipis di mana-mana.",hint:"Fokus pada satu-dua yang paling penting & bisa kamu pengaruhi."},
{n:96,type:"mcq",micro:"Tanda kamu makin menjadi warga aktif",q:"Tanda sikap kewargaanmu berkembang:",options:["kamu makin sering berkata 'itu bukan urusanku' setiap melihat masalah, & berhenti peduli supaya hidupmu tak direpotkan","kamu hanya mau terlibat ketika ada yang memuji atau memberi hadiah, lalu berhenti begitu pekerjaannya mulai sulit dan tidak ada lagi orang yang memperhatikan","kamu lebih cepat melihat masalah sebagai sesuatu yang bisa diikhtiarkan, mengajak orang lain, & menindaklanjuti sampai selesai"],answer:2,explain:"Pertumbuhan tampak dari rasa berdaya, kebiasaan mengajak, & ketekunan menindaklanjuti.",hint:"Melihat peluang berbuat, mengajak, menindaklanjuti."},
{n:97,type:"mcq",micro:"Kebiasaan warga yang berkontribusi",q:"Manakah kumpulan kebiasaan warga yang peduli & berkontribusi?",options:["ikut kerja bakti, melapor masalah lewat jalur resmi, membantu tetangga, memulai program bermanfaat, & menjalankannya secara berkelanjutan","hanya menikmati fasilitas yang ada, mengeluh tanpa berbuat apa-apa, menolak ajakan membantu, & berharap orang lain yang membereskan masalah di lingkungan","berkontribusi hanya bila ada kamera yang merekam atau hadiah yang bisa langsung diterima, lalu berhenti begitu perhatian orang beralih ke hal yang lain"],answer:0,explain:"Kebiasaan kecil yang konsisten di berbagai lingkaran kehidupan inilah wujud kewargaan aktif.",hint:"Kerja bakti, lapor, bantu tetangga, mulai program, berkelanjutan."},
{n:98,type:"mcq",micro:"Saat ragu bagaimana mulai berkontribusi",q:"Aturan sederhana saat bingung mulai dari mana:",options:["tunggu sampai ada orang lain yang memulai lebih dulu, baru kemudian kamu ikut membantu seperlunya","pilih satu masalah nyata yang dekat denganmu, lakukan satu langkah kecil minggu ini, & ajak satu orang lain ikut","tunggu sampai kamu punya banyak waktu luang & uang yang cukup baru mulai melakukan sesuatu yang berguna"],answer:1,explain:"Memulai dari yang dekat & kecil, lalu mengajak satu orang, membuat kontribusi terasa mungkin & bisa bertumbuh.",hint:"Satu masalah dekat, satu langkah kecil, satu ajakan."},
{n:99,type:"mcq",micro:"Mengajari yang lebih muda",q:"Cara membantu adik menjadi warga yang peduli:",options:["menyuruhnya ikut kegiatan tanpa penjelasan, memarahinya bila menolak, & membiarkannya berpikir bahwa urusan lingkungan bukan urusan anak-anak","melakukan semua kegiatan sendirian tanpa mengajaknya, lalu memamerkan hasilnya agar ia merasa kurang dan terpaksa ikut karena malu bukan karena mengerti manfaatnya","ajak ia ikut kegiatan sederhana (menyapa tetangga, ikut kerja bakti, merapikan taman), jelaskan manfaatnya, & puji usahanya"],answer:2,explain:"Anak belajar kewargaan lewat pengalaman ikut serta & teladan orang di sekitarnya.",hint:"Ajak ikut kegiatan sederhana + jelaskan + puji."},
{n:100,type:"mcq",micro:"Sintesis",q:"Inti dari 'Menjadi Warga yang Peduli & Berkontribusi', & dari seluruh tema Kewargaan & Lingkungan, adalah...",options:["menjadi warga yang baik berarti menaati aturan yang adil & menyuarakan yang tidak adil, menghormati semua orang, ikut memutuskan lewat musyawarah, menjaga milik bersama & lingkungan, serta mengambil bagian, sesuai kemampuan, untuk memperbaiki masyarakat, kini & untuk generasi berikutnya","menjadi warga yang baik cukup dengan mematuhi aturan & tidak mengganggu orang lain, sedangkan memperbaiki masyarakat serta menjaga milik bersama dan lingkungan adalah tugas pemerintah dan orang dewasa saja, bukan tugas pelajar, kini maupun nanti","warga yang baik adalah yang paling banyak menuntut haknya dan mengkritik keadaan, tanpa perlu ikut bermusyawarah, menjaga milik bersama & lingkungan, atau mengambil bagian dalam kegiatan masyarakat di sekitarnya, selama ia merasa dirugikan oleh orang lain"],answer:0,explain:"Kewargaan yang utuh menggabungkan hak & kewajiban, penghormatan pada keberagaman, musyawarah, tanggung jawab pada milik bersama & lingkungan, & kontribusi nyata yang berkelanjutan.",hint:"Taat & suarakan keadilan + hormati semua + musyawarah + jaga milik bersama & lingkungan + berkontribusi."},
];
